  'Relay fallback': 'Terugval van relais',
  'The computer must allow relay in its pairing QR. For a Direct-only pairing, generate a new Dovo-enabled QR on the computer and pair again.':
    'De computer moet relais toestaan in zijn koppelings-QR. Voor een directe koppeling genereert u een nieuwe Dovo-compatibele QR op de computer en koppelt u opnieuw.',
