  'Pair again': 'Koppel opnieuw',
  'Connection stages': 'Verbindingsfasen',
  'Start your computer': 'Start uw computer',
  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Open Dovo op uw computer en houd deze wakker. Meld u aan in Instellingen → Apparaten en runtime en schakel Dovo Connect in. Meld u op uw telefoon aan bij hetzelfde account en kies Verbinden. Er is geen koppelingscode, VPN of lokaal IP-adres nodig voor internettoegang.',
  'Direct internet connection': 'Directe internetverbinding',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN verbindt uw telefoon rechtstreeks met de computer. Uw inhoud is end-to-end gecodeerd. Door Dovo Connect in te schakelen is een gecodeerde relay-fallback mogelijk als een netwerk directe verbindingen blokkeert. Het relais stuurt versleuteld verkeer door; het kan uw inhoud niet lezen.',
  'LAN / VPN connections': 'LAN/VPN-verbindingen',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Koppel LAN/VPN afzonderlijk om de voorkeur te geven aan die verbinding, indien beschikbaar. Kopieer het volledige Wi-Fi-, Tailscale-, NetBird- of HTTPS-adres dat op uw computer wordt weergegeven, inclusief de poort. localhost en 0.0.0.0 zijn geen adressen waarmee uw telefoon verbinding kan maken.',
  'Check your network': 'Controleer uw netwerk',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Gebruik dezelfde Wi-Fi of verbind beide apparaten met uw VPN. Voor Wi-Fi-verbindingen geeft u Dovo toegang tot uw lokale netwerk in iPhone-instellingen.',
