  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Voert de agent van elk nieuw gesprek, zijn opdrachten en zijn terminals uit in een lokale Docker- of Podman-container. Alleen de werkkopie en de login van de gekozen agent worden gekoppeld. Lopende gesprekken behouden hun instelling.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Zonder netwerktoegang kan de agent zijn model-API niet bereiken, tenzij die API in de sandbox draait. Pakketinstallaties en webverzoeken mislukken ook.',
