  'The agent, its commands and its terminals run in a container. Only this checkout and the harness login are mounted.':
    'De agent, zijn opdrachten en zijn terminals draaien in een container. Alleen deze werkkopie en de login van de agent worden gekoppeld.',
  'Holds new work that runs without your message once its estimated cost reaches the limit. This covers Bot follow-ups, Bot routine steps, scheduled messages and child agents. Each thread or Bot counts with its child agents. A routine without a Bot starts a new count on each run. Set its own limits in Monitoring and limits. Your next message or Continue resets the count. Turns without a price also hold work. A running turn always finishes.':
    'Houdt nieuw werk dat zonder jouw bericht draait vast zodra de geschatte kosten de limiet bereiken. Dit geldt voor Bot-vervolgstappen, routinestappen van een Bot, geplande berichten en subagents. Elke thread of Bot telt samen met zijn subagents. Een routine zonder Bot begint bij elke run een nieuwe telling. Stel daarvoor de eigen limieten in bij Toezicht en limieten. Je volgende bericht of Doorgaan zet de telling terug. Beurten zonder prijs houden ook werk vast. Een lopende beurt maakt altijd zijn werk af.',
